<h1><?= e(__('Đặt mật khẩu mới')) ?></h1>
<?php if(!$resetToken): ?><p class="alert alert-danger"><?= e(__('Liên kết không hợp lệ, đã hết hạn hoặc đã sử dụng.')) ?></p><a class="btn btn-primary" href="<?= e(url('/forgot-password')) ?>"><?= e(__('Yêu cầu liên kết mới')) ?></a>
<?php else: ?><p class="auth-intro"><?= e(__('Mật khẩu mới cần có ít nhất 8 ký tự. Mật khẩu quá dài có thể bị từ chối, và chữ có dấu được tính nhiều hơn một ký tự. Sau khi đặt lại, các phiên cũ hết hiệu lực.')) ?></p><form method="post" action="<?= e(url('/reset-password')) ?>"><?= csrf_field() ?><input type="hidden" name="token" value="<?= e($resetToken) ?>"><label for="reset-password"><?= e(__('Mật khẩu mới')) ?></label><input class="form-control mb-3" id="reset-password" type="password" name="password" autocomplete="new-password" required><label for="reset-confirm"><?= e(__('Nhập lại mật khẩu')) ?></label><input class="form-control mb-3" id="reset-confirm" type="password" name="password_confirmation" autocomplete="new-password" required><button class="btn btn-primary btn-block"><?= e(__('Đặt lại mật khẩu')) ?></button></form><?php endif; ?>
